content:
:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #0f172a;
  color: #f8fafc;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  width: 100%;
  max-width: 600px;
  height: 100vh;
  max-height: 800px;
  background-color: #1e293b;
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
  border-radius: 12px;
  overflow: hidden;
}

@media (min-width: 640px) {
  .app-container {
    height: 85vh;
  }
}

.header {
  padding: 16px 20px;
  background-color: #0f172a;
  border-bottom: 1px solid #334155;
  text-align: center;
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  color: #38bdf8;
  letter-spacing: 0.05em;
}

.canvas-container {
  flex: 1;
  width: 100%;
  position: relative;
  background: radial-gradient(circle at center, #334155 0%, #0f172a 100%);
  touch-action: none;
  overflow: hidden;
}

.controls {
  padding: 16px 20px;
  background-color: #0f172a;
  border-top: 1px solid #334155;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  align-items: center;
}

.btn {
  background-color: #3b82f6;
  color: #ffffff;
  border: none;
  padding: 10px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s, box-shadow 0.2s;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn:hover {
  background-color: #2563eb;
  box-shadow: 0 6px 8px rgba(0, 0, 0, 0.3);
}

.btn:active {
  transform: scale(0.97);
}

.info-text {
  width: 100%;
  text-align: center;
  font-size: 0.85rem;
  color: #94a3b8;
  margin-top: 4px;
}

import { useEffect, useRef, useState, useCallback } from 'react';
import * as THREE from 'three';
import './index.css';

export default function App() {
  const mountRef = useRef<HTMLDivElement>(null);
  const [isAutoRotating, setIsAutoRotating] = useState<boolean>(true);
  const [cubeColor, setCubeColor] = useState<string>('#38bdf8');
  const [materialType, setMaterialType] = useState<'standard' | 'wireframe' | 'normal'>('standard');

  const cubeRef = useRef<THREE.Mesh | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);

  const isDraggingRef = useRef<boolean>(false);
  const previousMousePositionRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });

  const colors = ['#38bdf8', '#f43f5e', '#10b981', '#fbbf24', '#a855f7'];

  useEffect(() => {
    const currentMount = mountRef.current;
    if (!currentMount) return;

    // Scene
    const scene = new THREE.Scene();

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      currentMount.clientWidth / currentMount.clientHeight,
      0.1,
      1000
    );
    camera.position.z = 5;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    currentMount.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0xffffff, 1.5);
    pointLight.position.set(5, 5, 5);
    scene.add(pointLight);

    // Cube Geometry & Initial Material
    const geometry = new THREE.BoxGeometry(2, 2, 2);
    let material: THREE.Material;
    if (materialType === 'wireframe') {
      material = new THREE.MeshBasicMaterial({ color: cubeColor, wireframe: true });
    } else if (materialType === 'normal') {
      material = new THREE.MeshNormalMaterial();
    } else {
      material = new THREE.MeshStandardMaterial({
        color: cubeColor,
        roughness: 0.3,
        metalness: 0.8,
      });
    }

    const cube = new THREE.Mesh(geometry, material);
    scene.add(cube);
    cubeRef.current = cube;

    // Animation Loop
    let animationFrameId: number;
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      if (isAutoRotating && !isDraggingRef.current && cubeRef.current) {
        cubeRef.current.rotation.x += 0.005;
        cubeRef.current.rotation.y += 0.007;
      }

      renderer.render(scene, camera);
    };
    animate();

    // Resize Handler
    const handleResize = () => {
      if (!currentMount) return;
      const width = currentMount.clientWidth;
      const height = currentMount.clientHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
      if (currentMount && renderer.domElement) {
        currentMount.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, []);

  // Update material or color when state changes
  useEffect(() => {
    if (!cubeRef.current) return;
    let material: THREE.Material;
    if (materialType === 'wireframe') {
      material = new THREE.MeshBasicMaterial({ color: cubeColor, wireframe: true });
    } else if (materialType === 'normal') {
      material = new THREE.MeshNormalMaterial();
    } else {
      material = new THREE.MeshStandardMaterial({
        color: cubeColor,
        roughness: 0.3,
        metalness: 0.8,
      });
    }
    cubeRef.current.material = material;
  }, [cubeColor, materialType]);

  // Pointer event handlers for manual rotation
  const handlePointerDown = (e: React.PointerEvent) => {
    isDraggingRef.current = true;
    previousMousePositionRef.current = { x: e.clientX, y: e.clientY };
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDraggingRef.current || !cubeRef.current) return;

    const deltaX = e.clientX - previousMousePositionRef.current.x;
    const deltaY = e.clientY - previousMousePositionRef.current.y;

    cubeRef.current.rotation.y += deltaX * 0.01;
    cubeRef.current.rotation.x += deltaY * 0.01;

    previousMousePositionRef.current = { x: e.clientX, y: e.clientY };
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    isDraggingRef.current = false;
    try {
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    } catch {
      // Ignore if capture failed or already released
    }
  };

  const handleReset = useCallback(() => {
    if (!cubeRef.current) return;
    cubeRef.current.rotation.set(0, 0, 0);
    setIsAutoRotating(true);
  }, []);

  const toggleAutoRotate = useCallback(() => {
    setIsAutoRotating(prev => !prev);
  }, []);

  const changeColor = useCallback(() => {
    setCubeColor(prevColor => {
      const currentIndex = colors.indexOf(prevColor);
      const nextIndex = (currentIndex + 1) % colors.length;
      return colors[nextIndex];
    });
  }, [colors]);

  const toggleMaterial = useCallback(() => {
    setMaterialType(prev => {
      if (prev === 'standard') return 'wireframe';
      if (prev === 'wireframe') return 'normal';
      return 'standard';
    });
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">3D 立方体ビューア</h1>
      </header>

      <div 
        className="canvas-container"
        ref={mountRef}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
      />

      <footer className="controls">
        <button className="btn" onClick={toggleAutoRotate}>
          {isAutoRotating ? '自動回転: ON' : '自動回転: OFF'}
        </button>
        <button className="btn" onClick={changeColor}>
          カラー変更
        </button>
        <button className="btn" onClick={toggleMaterial}>
          質感: {materialType === 'standard' ? '標準' : materialType === 'wireframe' ? 'ワイヤー' : 'ノーマル'}
        </button>
        <button className="btn" onClick={handleReset}>
          リセット
        </button>
        <div className="info-text">
          マウスや指でドラッグして3D立方体を自由に回転させることができます
        </div>
      </footer>
    </div>
  );
}
